<?php require __DIR__ . "/../config/db.php"; $r = $conn->query("SELECT b.id, b.guest_name, b.accommodation_name, b.check_in, b.check_out, b.status, b.room_id FROM bookings b ORDER BY b.id DESC LIMIT 10"); while($row = $r->fetch_assoc()) { echo $row["id"] . " | " . $row["guest_name"] . " | " . $row["accommodation_name"] . " | " . $row["check_in"] . " to " . $row["check_out"] . " | room_id=" . $row["room_id"] . " | " . $row["status"] . "\n"; } ?>
